61.   @Override
62.   public ResultSet execute() {
63.     if (graph.database instanceof RemoteDatabase)
64.       return graph.database.command("gremlin", query);
65. 
66.     try {
67.       final boolean profileExecution = parameters != null && parameters.containsKey("$profileExecution") ?
68.           (Boolean) parameters.remove("$profileExecution") :
69.           false;
70. 
71.       final Iterator<?> resultSet = executeStatement();
72. 
73.       ExecutionPlan executionPlan = null;
74.       if (profileExecution) {
75.         final String originalQuery = query;
76.         query += ".profile()";
77.         try {
78.           final Iterator<?> profilerResultSet = executeStatement();
79.           if (profilerResultSet.hasNext()) {
80.             final Object result = profilerResultSet.next();
81.             executionPlan = new ExecutionPlan() {
82.               @Override
83.               public List<ExecutionStep> getSteps() {
84.                 return null;
85.               }
86. 
87.               @Override
88.               public String prettyPrint(int depth, int indent) {
89.                 return result.toString();
90.               }
91. 
92.               @Override
93.               public Result toResult() {
94.                 return null;
95.               }
96.             };
97.           }
98.         } catch (Exception e) {
99.           // NO EXECUTION PLAN
100.         } finally {
101.           query = originalQuery;
102.         }
103.       }
104. 
105.       final ExecutionPlan activeExecutionPlan = executionPlan;
106. 
107.       final IteratorResultSet result = new IteratorResultSet(new Iterator() {
108.         @Override
109.         public boolean hasNext() {
110.           return resultSet.hasNext();
111.         }
112. 
113.         @Override
114.         public Object next() {
115.           final Object next = resultSet.next();
116.           if (next instanceof Document document)
117.             return new ResultInternal(document);
118.           else if (next instanceof ArcadeElement<?> element)
119.             return new ResultInternal(element.getBaseElement());
120.           else if (next instanceof Map) {
121.             final Map<String, Object> stringMap = getStringObjectMap((Map<Object, Object>) next);
122. 
123.             return new ResultInternal(stringMap);
124.           }
125.           return new ResultInternal(Map.of("result", next));
126.         }
127.       }) {
128.         @Override
129.         public Optional<ExecutionPlan> getExecutionPlan() {
130.           return activeExecutionPlan != null ? Optional.of(activeExecutionPlan) : Optional.empty();
131.         }
132.       };
