142.     // TRANSFORM TO A MAP WITH STRINGS AS KEYS
143.     final Map<Object, Object> map = originalMap;
144.     final Map<String, Object> stringMap = new LinkedHashMap<>(originalMap.size());
145. 
146.     for (Map.Entry<Object, Object> entry : map.entrySet())
147.       stringMap.put(entry.getKey().toString(), entry.getValue());
148.     return stringMap;
