151.   public QueryEngine.AnalyzedQuery parse() {
152.     try {
153.       final DefaultGraphTraversal<?,?> resultSet = (DefaultGraphTraversal<?,?>) executeStatement();
154. 
155.       boolean idempotent = true;
156.       for (final Object step : resultSet.getSteps()) {
157.         if (step instanceof Mutating) {
158.           idempotent = false;
159.           break;
160.         }
161.       }
162. 
163.       final boolean isIdempotent = idempotent;
164. 
165.       return new QueryEngine.AnalyzedQuery() {
166.         @Override
167.         public boolean isIdempotent() {
168.           return isIdempotent;
169.         }
170. 
171.         @Override
172.         public boolean isDDL() {
173.           return false;
174.         }
175.       };
176.     } catch (Exception e) {
