     try {
       final DefaultGraphTraversal<?,?> resultSet = (DefaultGraphTraversal<?,?>) executeStatement();

       boolean idempotent = true;
       for (final Object step : resultSet.getSteps()) {
         if (step instanceof Mutating) {
