169.   private static CypherQueryAndParameters expandAllKeysPattern(CypherQueryAndParameters queryAndParams) {
170.     String query = queryAndParams.cypherQuery;
171.     Map<String, Object> parameters = new HashMap<>(queryAndParams.parameters);
172. 
173.     // Pattern: ALL(variableName IN keys($paramName) WHERE nodeVar[variableName] = $paramName[variableName])
