175.     java.util.regex.Pattern pattern = java.util.regex.Pattern.compile(
176.         "ALL\\s*\\(\\s*(\\w+)\\s+IN\\s+keys\\s*\\(\\s*\\$([\\w]+)\\s*\\)\\s+WHERE\\s+(\\w+)\\s*\\[\\s*\\1\\s*\\]\\s*=\\s*\\$\\2\\s*\\[\\s*\\1\\s*\\]\\s*\\)",
