186.       String paramName = matcher.group(2);      // e.g., "props" (the randomized parameter name)
187.       String nodeVar = matcher.group(3);        // e.g., "n"
188. 
189.       // Get the parameter value (should be a Map)
190.       Object paramValue = parameters.get(paramName);
191. 
192.       if (paramValue instanceof Map<?, ?> paramMap) {
193.         // Build the expanded condition
194.         StringBuilder expanded = new StringBuilder();
195.         boolean first = true;
196. 
197.         for (Map.Entry<?, ?> entry : paramMap.entrySet()) {
198.           String key = entry.getKey().toString();
199.           Object value = entry.getValue();
200. 
201.           if (!first) {
202.             expanded.append(" AND ");
203.           }
204.           first = false;
205. 
206.           // Create a new parameter for this specific key
207.           String newParamName = paramName + "_" + key;
208.           expanded.append(nodeVar).append(".").append(key).append(" = $").append(newParamName);
