210.         }
211. 
212.         // If the map is empty, this should always be true (vacuous truth)
213.         if (paramMap.isEmpty()) {
214.           expanded.append("true");
215.         }
216. 
217.         // Replace the ALL pattern with the expanded condition
218.         result.append(query, lastEnd, matcher.start());
