252.     Map<String, Object> updatedParameters = new HashMap<>();
253.     for (Map.Entry<String, Object> entry : parameters.entrySet()) {
254.       updatedParameters.put(replacementMap.get(entry.getKey()), entry.getValue());
255.     }
256. 
257.     return new CypherQueryAndParameters(newCypher, updatedParameters);
258.   }
