94.                 return null;
95.               }
96.             };
97.           }
98.         } catch (Exception e) {
99.           // NO EXECUTION PLAN
100.         } finally {
101.           query = originalQuery;
102.         }
103.       }
104. 
105.       final ExecutionPlan activeExecutionPlan = executionPlan;
106. 
107.       final IteratorResultSet result = new IteratorResultSet(new Iterator() {
108.         @Override
