190.   private Iterator<?> executeStatement() throws ScriptException {
191.     final BasicDatabase database = graph.getDatabase();
192.     String gremlinEngine = database instanceof Database d ?
193.         d.getConfiguration().getValueAsString(GlobalConfiguration.GREMLIN_ENGINE) :
194.             GlobalConfiguration.GREMLIN_ENGINE.getValueAsString();
195. 
196.     if ("auto".equals(gremlinEngine)) {
197.       if (parameters == null || parameters.isEmpty()) {
198.         // NO PARAMETERS, USES THE NEW ENGINE
199.         try {
200.           return executeStatement("java");
201.         } catch (ScriptException e) {
202.           // EXCEPTION PARSING, TRYING WITH OLD GROOVY PARSER
203.           LogManager.instance()
204.               .log(this, Level.FINE, "The gremlin query '%s' could not be parsed, using the legacy `groovy` parser", e, query);
205.         }
206.       }
207.       gremlinEngine = "groovy";
208.     }
209. 
210.     return executeStatement(gremlinEngine);
