213.   private Iterator<?> executeStatement(final String gremlinEngine) throws ScriptException {
214.     final Object result;
215.     if ("java".equals(gremlinEngine)) {
216.       // USE THE NATIVE GREMLIN PARSER
217.       final GremlinLangScriptEngine gremlinEngineImpl = graph.getGremlinJavaEngine();
218. 
219.       final SimpleBindings bindings = new SimpleBindings();
220.       bindings.put("g", graph.traversal());
221.       if (parameters != null)
222.         bindings.putAll(parameters);
223. 
224.       result = gremlinEngineImpl.eval(query, bindings);
225. 
226.     } else if ("groovy".equals(gremlinEngine)) {
227.       // GROOVY ENGINE - INSECURE, LOG WARNING
228.       LogManager.instance().log(this, Level.WARNING,
229.           "SECURITY WARNING: Using insecure Groovy Gremlin engine. This engine is vulnerable to Remote Code Execution (RCE) attacks. " +
230.           "Authenticated users can execute arbitrary operating system commands. DO NOT USE IN PRODUCTION. " +
231.           "Switch to the secure Java engine (arcadedb.gremlin.engine=java) immediately.");
232. 
233.       final GremlinGroovyScriptEngine gremlinEngineImpl = graph.getGremlinGroovyEngine();
234. 
235.       final SimpleBindings bindings = new SimpleBindings();
236.       bindings.put("g", graph.traversal());
237.       if (parameters != null)
238.         bindings.putAll(parameters);
239.       result = gremlinEngineImpl.eval(query, bindings);
240. 
241.     } else
242.       throw new IllegalArgumentException("Gremlin engine '" + gremlinEngine + "' not supported");
243. 
244.     if (result instanceof GraphTraversal<?,?> traversal)
245.       return traversal;
246. 
247.     return Set.of(result).iterator();
248.   }
