271.     final String mapKey = graph.getDatabase().getDatabasePath() + ":";
272. 
273.     // REMOVE ALL THE ENTRIES RELATIVE TO THE CLOSED DATABASE
274.     STATEMENT_CACHE.entrySet().removeIf(stringCachedStatementEntry -> stringCachedStatementEntry.getKey().startsWith(mapKey));
275.   }
