277.   private static void cacheLastStatement(String cypher, String gremlin) {
278.     if (CACHE_SIZE > 0) {
279.       // REMOVE THE OLDEST TO MAKE ROOM FOR THE LATEST STATEMENT
280.       while (STATEMENT_CACHE.size() >= CACHE_SIZE) {
281.         int leastUsedValue = 0;
282.         String leastUsedKey = null;
283. 
284.         for (final Map.Entry<String, CachedStatement> entry : STATEMENT_CACHE.entrySet()) {
285.           if (leastUsedKey == null || entry.getValue().used < leastUsedValue) {
286.             leastUsedKey = entry.getKey();
287.             leastUsedValue = entry.getValue().used;
288.           }
289.         }
290.         STATEMENT_CACHE.remove(leastUsedKey);
291.       }
292.       STATEMENT_CACHE.put(cypher, new CachedStatement(cypher, gremlin));
293.     }
294.   }
