         else if (singleQuoted && c == '\'')
           singleQuoted = false;
         else if (doubleQuoted && c == '"')
           doubleQuoted = false;
         ++i;
         continue;
       }

       if (c == '\'') {
         singleQuoted = true;
         result.append(c);
         ++i;
         continue;
       }
       if (c == '"') {
         doubleQuoted = true;
         result.append(c);
         ++i;
         continue;
       }

